create or replace function public.accept_invitation(invitation_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare inv public.invitations;verified_email text;has_valid_method boolean;begin select exists(select 1 from jsonb_array_elements(coalesce(auth.jwt()->'amr','[]'::jsonb)) a where a->>'method' in ('password','oauth','invite')) into has_valid_method;if not has_valid_method then raise exception 'Password setup or authenticated login required';end if;select lower(email) into verified_email from auth.users where id=auth.uid() and email_confirmed_at is not null;if verified_email is null then raise exception 'Verified sign-in required';end if;select * into inv from public.invitations where id=invitation_id and status='pending' and email=verified_email for update;if inv.id is null then raise exception 'Invitation unavailable';end if;insert into public.organization_members(organization_id,user_id,role) values(inv.organization_id,auth.uid(),inv.role) on conflict(organization_id,user_id) do nothing;update public.invitations set status='accepted',accepted_by=auth.uid(),accepted_at=now() where id=inv.id;return inv.organization_id;end $$;
create function public.organization_team(org_id uuid) returns table(id uuid,user_id uuid,display_name text,email text,role public.org_role,created_at timestamptz) language plpgsql stable security definer set search_path=public as $$ begin if not(public.is_platform_admin() or public.has_org_role(org_id,array['owner','admin']::public.org_role[])) then raise exception 'Unauthorized';end if;return query select m.id,m.user_id,p.display_name,u.email::text,m.role,m.created_at from public.organization_members m join public.profiles p on p.id=m.user_id join auth.users u on u.id=m.user_id where m.organization_id=org_id order by m.created_at;end $$;
revoke all on function public.organization_team(uuid) from public,anon;grant execute on function public.organization_team(uuid) to authenticated;
